    public static function has(string $key): bool
    {
        return isset(self::MAP[$key]);
    }

    /** @return list<string> */
    public static function keys(): array
    {
        return array_keys(self::MAP);
    }

    public static function type(string $key): string
    {
        return self::MAP[$key][0] ?? throw new \InvalidArgumentException("Unknown icon: {$key}");
    }

    public static function render(string $key, string $extraClass = ''): string
    {
        $type = self::type($key);
        $class = 'icon-' . $type . ($extraClass !== '' ? ' ' . $extraClass : '');

        return '<svg class="' . $class . '" viewBox="0 0 24 24" aria-hidden="true" focusable="false">'
            . self::MAP[$key][1]
            . '</svg>';
    }
